//   Boulder "maze" with wide corridors

/** @param {{des: object}} api */
export default function bigrm_11({ des, selection, nh, percent }) {
    function t_or_f() {
        return percent(50) && true || false;
    }

    des.level_flags('mazelevel', 'noflip');
    des.level_init({ style: 'maze', corrwid: 3 + nh.rn2(3), wallthick: 1, deadends: t_or_f() });

    des.region(selection.area(0, 0, 75, 18), 'lit');
    des.non_diggable();

    function replace_wall_boulder(x, y) {
        des.terrain(x, y, '.');
        des.object('boulder', x, y);
    }

    // replace horizontal and vertical walls
    let sel = selection.bor(selection.match(`.w.`), selection.match('.\nw\n.'));
    selection.iterate(sel, replace_wall_boulder);
    // replace the leftover corner walls
    sel = selection.match(`.w.`);
    selection.iterate(sel, replace_wall_boulder);

    des.stair('up');
    des.stair('down');

    for (let i = 1; i <= 15; i++) {
        des.object();
    }
    for (let i = 1; i <= 6; i++) {
        des.trap('rolling boulder');
    }
    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
